m_44aedcbe21306bdbe3c42eb7"], "query_ids": ["q_476"], "claims": [{"claim_id": "claim_09aafdefb421cf062a3c402b", "quote": "imposing tariffs of 100 percent on certain ship-to-shore cranes and cargo handling equipment.", "url": "https://ustr.gov/about/policy-offices/press-office/press-releases/2025/october/ustr-modifies-certain-aspects-section-301-ships-action-and-proposes-further-modifications-action", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "ship-to-shore cranes and cargo handling equipment", "duty_rate": "100 percent", "effective_date": "October 14, 2025"}}, {"claim_id": "claim_44aedcbe21306bdbe3c42eb7", "quote": "the U.S. Trade Representative has determined to impose additional duties of 100 percent on STS cranes as described in Annex V.A to this notice", "url": "https://ustr.gov/sites/default/files/files/Press/Releases/2025/301%20Ships%20Action%20Mod%20FRN.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "100 percent", "effective_date": "April 17, 2025"}}]}, {"pair_id": "conflict_b6e969e36512cc29b2b8e906", "claim_ids": ["claim_05a82eb4e975a0df5e77df29", "claim_0f00d987a85c219547b30dd4"], "query_ids": ["q_476"], "claims": [{"claim_id": "claim_05a82eb4e975a0df5e77df29", "quote": "impose additional tariffs of up to 150 percent on other cargo handling equipment, including: rubber tire gantry cranes, rail mounted gantry cranes, automatic staking cranes, reachstackers, straddle carriers, terminal tractors, top handlers (which may also be referred to as top loaders), and parts of these machines.", "url": "https://ustr.gov/sites/default/files/files/Press/Releases/2025/301%20Ships%20Action%20Mod%20FRN.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "up to 150 percent", "announcement_date": "April 18, 2029"}}, {"claim_id": "claim_0f00d987a85c219547b30dd4", "quote": "Annex V.B: Add a new Annex V.B and impose additional tariffs of up to 150 percent on other cargo handling equipment, including: rubber tire gantry cranes, rail mounted gantry cranes, automatic staking cranes, reachstackers, straddle carriers, terminal tractors, top handlers (which may also be referred to as top loaders), and parts of these machines.", "url": "https://ustr.gov/sites/default/files/files/Press/Releases/2025/301%20Ships%20Action%20Mod%20FRN.pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "rubber tire gantry cranes, rail mounted gantry cranes, automatic staking cranes, reachstackers, straddle carriers, terminal tractors, top handlers (which may also be referred to as top loaders), and parts of these machines", "duty_rate": "up to 150 percent"}}]}, {"pair_id": "conflict_90bf35e928044ee2c0172674", "claim_ids": ["claim_7969f3829a7336ee3009ca33", "claim_7db67bc00acfe03b44d35c67"], "query_ids": ["q_476"], "claims": [{"claim_id": "claim_7969f3829a7336ee3009ca33", "quote": "imposing additional tariffs of up to 150 percent on certain cargo handling equipment (e.g., rubber tire gantry cranes) and components of such equipment.", "url": "https://ustr.gov/about/policy-offices/press-office/press-releases/2025/october/ustr-modifies-certain-aspects-section-301-ships-action-and-proposes-further-modifications-action", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "cargo handling equipment (e.g., rubber tire gantry cranes) and components of such equipment", "duty_rate": "up to 150 percent"}}, {"claim_id": "claim_7db67bc00acfe03b44d35c67", "quote": "imposing additional duties of 100 percent on ship-to-shore (STS) cranes and duties of 100 percent on certain cargo handling equipment of China as described in Annex V.A of this notice.", "url": "https://ustr.gov/sites/default/files/files/Press/Releases/2025/301%20Ships%20Action%20Mod%20FRN.pdf", "kind": "full_document", "publisher_type": "official_trade_aut